-- Exercise library expansion · authored under Exercise Science Advisor review.
-- Same controlled vocabulary as 0002_seed_exercises.sql (movement patterns,
-- contraindication tags). Global rows (trainer_id NULL). Adds CrossFit,
-- functional movement, Hyrox, HIIT, yoga, mat Pilates, and senior-specific
-- exercises.

insert into exercises
  (name, description, pattern, muscle_groups, equipment_types, difficulty, cues, contraindication_tags, unilateral)
values

-- CROSSFIT ────────────────────────────────────────────────────────────
('Thruster', 'Front squat driven directly into an overhead press in one motion.', 'squat', '{quads,glutes,shoulders}', '{barbell}', 'advanced', E'Elbows high in the front rack\nStand up and press in one fluid motion\nFull lockout overhead', '{overhead,deep_knee_flexion,front_rack}', false),
('Wall Ball', 'Squat to a throw, catching the medicine ball and repeating.', 'squat', '{quads,glutes,shoulders}', '{medicine_ball}', 'intermediate', E'Squat below parallel\nDrive up and extend through the throw\nCatch soft, absorb into the next squat', '{deep_knee_flexion}', false),
('Kettlebell Snatch', 'Explosive one-arm pull from the floor to an overhead lockout.', 'conditioning', '{glutes,hamstrings,shoulders}', '{kettlebell}', 'advanced', E'Hike pass, then explosive hip snap\nPunch through at the top\nSoft-catch on the way down', '{overhead}', true),
('Box Jump', 'Explosive two-foot jump onto a box.', 'conditioning', '{quads,glutes}', '{box}', 'intermediate', E'Full hip extension at the top\nStep down, don''t jump down\nReset between reps if fatigued', '{high_impact,knee_dominant_plyo,deep_knee_flexion}', false),
('Double Unders', 'Jump rope passing under the feet twice per jump.', 'conditioning', '{calves,shoulders}', '{jump_rope}', 'intermediate', E'Small hop, wrists do the work\nStay tall, quiet landing', '{high_impact}', false),
('Toes-to-Bar', 'Hanging from a bar, raise the feet to touch it.', 'core_flexion', '{core,hip_flexors}', '{pullup_bar}', 'advanced', E'Initiate from a hollow hang\nControl the descent, no wild swinging', '{loaded_flexion,high_grip_demand,overhead}', false),
('Pistol Squat', 'Single-leg squat to full depth with the other leg extended forward.', 'squat', '{quads,glutes}', '{bodyweight}', 'advanced', E'Reach arms forward for balance\nSit back into the working hip\nControl through the bottom', '{deep_knee_flexion,single_leg_unstable}', true),
('Devil Press', 'Burpee combined with a two-dumbbell snatch to overhead.', 'conditioning', '{full_body}', '{dumbbell}', 'advanced', E'Chest to floor on the burpee\nHike the bells back, snatch to lockout\nPace this one — it adds up fast', '{high_impact,overhead,wrist_extension_load}', false),

-- FUNCTIONAL MOVEMENT ────────────────────────────────────────────────
('Turkish Get-Up', 'Floor-to-standing sequence keeping a weight locked out overhead throughout.', 'core_antirotation', '{core,shoulders}', '{kettlebell}', 'advanced', E'Eyes on the bell the whole way up\nMove slow, own each position\nReverse the pattern with the same control going down', '{overhead,supine_extended,loaded_rotation}', true),
('Suitcase Deadlift', 'One-sided deadlift with the load at the side rather than centered.', 'hinge', '{glutes,hamstrings,core}', '{kettlebell}', 'intermediate', E'Resist leaning toward the load\nHips and shoulders stay square\nStand tall at the top', '{heavy_spinal_load}', true),
('Bear Crawl', 'Crawl forward on hands and feet with knees hovering off the floor.', 'conditioning', '{core,shoulders}', '{bodyweight}', 'intermediate', E'Knees stay low, don''t rise up\nOpposite hand and foot move together\nFlat back throughout', '{wrist_extension_load,prone}', false),
('Medicine Ball Rotational Throw', 'Rotate through the trunk to throw a medicine ball against a wall.', 'core_antirotation', '{core,obliques}', '{medicine_ball}', 'intermediate', E'Rotate from the hips, not just the arms\nFull extension into the throw\nCatch and immediately load the next rep', '{loaded_rotation}', true),
('Single-Leg Romanian Deadlift', 'Hip hinge balanced on one leg, the other extending behind.', 'hinge', '{hamstrings,glutes}', '{dumbbell}', 'intermediate', E'Hips square to the floor\nReach the free leg back as you hinge\nLight touch of the working knee is fine', '{single_leg_unstable}', true),
('Lateral Lunge', 'Step wide to one side and sit back into that hip.', 'lunge', '{quads,glutes,adductors}', '{bodyweight}', 'beginner', E'Push hips back like sitting in a chair\nKeep the straight leg''s foot flat\nDrive back to center', '{deep_knee_flexion}', true),
('Renegade Row', 'Alternating dumbbell rows held in a plank position.', 'pull_horizontal', '{back,core}', '{dumbbell}', 'advanced', E'Minimize hip rotation as you row\nWide stance for a stable base\nRow to the hip pocket', '{wrist_extension_load}', true),
('Battle Ropes', 'Alternating or double-arm waves with heavy rope.', 'conditioning', '{shoulders,core}', '{battle_ropes}', 'intermediate', E'Athletic stance, knees soft\nWaves come from the shoulders, not just wrists\nKeep breathing rhythmic', '{}', false),

