('Sandbag Lunge', 'Walking or stationary lunge carrying a sandbag at the chest or shoulder.', 'lunge', '{quads,glutes}', '{sandbag}', 'intermediate', E'Torso stays tall despite the offset load\nControl the descent each step\nDrive through the front heel', '{deep_knee_flexion}', true),
('Burpee Broad Jump', 'A burpee immediately followed by a maximal forward jump.', 'conditioning', '{full_body}', '{bodyweight}', 'advanced', E'Full chest-to-floor burpee\nStick the landing before your next rep\nReset your stance between jumps', '{high_impact,wrist_extension_load,deep_knee_flexion}', false),

